import android.os.*;
/** Root-side bridge to the actual loaded Bluetooth process. Never treats submission as completion. */
public final class ProjectionBluetoothExclusiveClient {
 public static final class Binding {private final IBinder binder;private final String record,target;public final String incarnation;private Binding(IBinder b,String i,String r,String t){binder=b;incarnation=i;record=r;target=t;}}
 public static IBinder oemBinder()throws Exception{
  root();IBinder broker=(IBinder)Class.forName("android.os.ServiceManager").getMethod("checkService",String.class).invoke(null,"ev6.projection.discovery");if(broker==null||!broker.isBinderAlive())return null;
  Parcel in=Parcel.obtain(),out=Parcel.obtain();try{in.writeInterfaceToken("org.ev6.ProjectionDiscovery1");in.writeInt(5);if(!broker.transact(27,in,out,0))return null;out.readException();if(out.readInt()!=5)throw new IllegalStateException("bt-binding-version");String inc=out.readString();IBinder b=out.readStrongBinder();if(inc==null||!inc.matches("[0-9a-f-]{36}")||out.dataAvail()!=0||!broker.isBinderAlive())throw new IllegalStateException("bt-binding-owner");return b!=null&&b.isBinderAlive()?b:null;}finally{in.recycle();out.recycle();}
 }
 private static IBinder endpoint()throws Exception{
  IBinder oem=oemBinder();
  if(oem==null||!oem.isBinderAlive())return null;
  Parcel in=Parcel.obtain(),out=Parcel.obtain();try{in.writeInterfaceToken("org.ev6.BtExclusive1");in.writeInt(1);if(!oem.transact(0x45563601,in,out,0))return null;out.readException();if(out.readInt()!=1)throw new IllegalStateException("bt-export-version");IBinder b=out.readStrongBinder();if(out.dataAvail()!=0||b==null||!b.isBinderAlive()||!oem.isBinderAlive())throw new IllegalStateException("bt-export-owner");return b;}finally{in.recycle();out.recycle();}
 }
 public static boolean configured()throws Exception{IBinder b=endpoint();if(b==null)return false;Parcel in=Parcel.obtain(),out=Parcel.obtain();try{in.writeInterfaceToken("org.ev6.BtExclusive1");in.writeInt(1);if(!b.transact(0,in,out,0))return false;out.readException();if(out.readInt()!=1)throw new IllegalStateException("bt-cap-version");String inc=out.readString();return inc!=null&&inc.matches("[0-9a-f-]{36}")&&out.readInt()==9&&out.readInt()==1&&out.dataAvail()==0&&endpoint()==b&&b.isBinderAlive();}finally{in.recycle();out.recycle();}}

 private static void root(){if(android.os.Process.myUid()!=0)throw new SecurityException("exclusive-root");}
 public Binding requireExclusive(String record,String target)throws Exception{root();IBinder b=endpoint();if(b==null||!b.isBinderAlive())throw new IllegalStateException("exclusive-bt-unavailable");Parcel in=Parcel.obtain(),out=Parcel.obtain();try{
  in.writeInterfaceToken("org.ev6.BtExclusive1");in.writeInt(1);in.writeString(record);in.writeString(target);if(!b.transact(1,in,out,0))throw new IllegalStateException("exclusive-readback");out.readException();if(out.readInt()!=1)throw new IllegalStateException("exclusive-version");String incarnation=out.readString();if(incarnation==null||!incarnation.matches("[0-9a-f-]{36}")||out.readInt()!=9||out.readInt()!=1||out.dataAvail()!=0||endpoint()!=b||!b.isBinderAlive())throw new IllegalStateException("exclusive-not-drained");return new Binding(b,incarnation,record,target);
 }finally{in.recycle();out.recycle();}}
 /** Read-only explanation uses the same owner predicate as admission. Never a grant. */
 public String diagnostic(String record,String target)throws Exception{
  root();IBinder b=endpoint();if(b==null)return "owner-unavailable";Parcel in=Parcel.obtain(),out=Parcel.obtain();try{in.writeInterfaceToken("org.ev6.BtExclusive1");in.writeInt(1);in.writeString(record);in.writeString(target);if(!b.transact(4,in,out,0))throw new IllegalStateException("diagnostic-no-reply");out.readException();if(out.readInt()!=1)throw new IllegalStateException("diagnostic-version");String incarnation=out.readString();int revision=out.readInt();String reason=out.readString();if(incarnation==null||!incarnation.matches("[0-9a-f-]{36}")||revision!=9||reason==null||!reason.matches("[A-Za-z0-9-]{1,120}")||out.dataAvail()!=0||endpoint()!=b||!b.isBinderAlive())throw new IllegalStateException("diagnostic-owner");return incarnation+":"+reason;}finally{in.recycle();out.recycle();}
 }
 /** Returns 0=not dispatched, 1=submitted, 2=prior intent unknown, 3=no matching profiles. */
 public int disconnectOther(String record,String target,String peer)throws Exception{root();IBinder b=endpoint();if(b==null||!b.isBinderAlive())throw new IllegalStateException("exclusive-bt-unavailable");Parcel in=Parcel.obtain(),out=Parcel.obtain();try{
  in.writeInterfaceToken("org.ev6.BtExclusive1");in.writeInt(1);in.writeString(record);in.writeString(target);in.writeString(peer);if(!b.transact(2,in,out,0))throw new IllegalStateException("exclusive-stop-unacknowledged");out.readException();if(out.readInt()!=1)throw new IllegalStateException("exclusive-stop-version");String incarnation=out.readString();int result=out.readInt();if(incarnation==null||!incarnation.matches("[0-9a-f-]{36}")||result<0||result>3||out.dataAvail()!=0||endpoint()!=b)throw new IllegalStateException("exclusive-stop-unknown");return result;
 }finally{in.recycle();out.recycle();}}
 /** Exact current other-device work is revalidated on the OEM Handler at consumption. */
 public int cancelOtherWork(String record,String target)throws Exception{root();IBinder b=endpoint();if(b==null||!b.isBinderAlive())throw new IllegalStateException("cancel-bt-unavailable");Parcel in=Parcel.obtain(),out=Parcel.obtain();try{
  in.writeInterfaceToken("org.ev6.BtExclusive1");in.writeInt(1);in.writeString(record);in.writeString(target);if(!b.transact(5,in,out,0))throw new IllegalStateException("cancel-not-supported");out.readException();if(out.readInt()!=1)throw new IllegalStateException("cancel-version");String inc=out.readString();int result=out.readInt();if(inc==null||!inc.matches("[0-9a-f-]{36}")||result<0||result>3||out.dataAvail()!=0||endpoint()!=b||!b.isBinderAlive())throw new IllegalStateException("cancel-unknown");return result;
 }finally{in.recycle();out.recycle();}}
 public boolean retireLedger(String boot,String request,String predecessor)throws Exception{root();IBinder b=endpoint();if(b==null||!b.isBinderAlive())return false;Parcel in=Parcel.obtain(),out=Parcel.obtain();try{in.writeInterfaceToken("org.ev6.BtExclusive1");in.writeInt(1);in.writeString(boot);in.writeString(request);in.writeString(predecessor);if(!b.transact(3,in,out,0))throw new IllegalStateException("ledger-gc-no-reply");out.readException();if(out.readInt()!=1)throw new IllegalStateException("ledger-gc-version");String inc=out.readString();int done=out.readInt();if(inc==null||!inc.matches("[0-9a-f-]{36}")||(done!=0&&done!=1)||out.dataAvail()!=0||endpoint()!=b||!b.isBinderAlive())throw new IllegalStateException("ledger-gc-unknown");return done==1;}finally{in.recycle();out.recycle();}}
 public void verifyBinding(Binding binding)throws Exception{if(binding==null)throw new IllegalStateException("exclusive-owner-replaced");Binding current=requireExclusive(binding.record,binding.target);if(current.binder!=binding.binder||!current.incarnation.equals(binding.incarnation))throw new IllegalStateException("exclusive-owner-replaced");}
}
